// far calls through a pointer: the functions the program stores as pointers (a segment in any of the
// three encodings: Ghidra's, the image's, the loaded program's)
void st_far_call(u16 seg, u16 off)
{
  if (off == 0x4587 && (seg == 0x1000 || seg == 0x0000 || seg == 0x27cc)) { a_1000_4587(); return; }
  if (off == 0x4528 && (seg == 0x1000 || seg == 0x0000 || seg == 0x27cc)) { a_1000_4528(); return; }
  asm_unknown_call(seg, off);
}

// main (1000:0010), entered with its return address on the stack
void st_main_body(void) { a_1000_0010(); }
// the C library start-up (1000:5006), the entry of the executable, as DOS starts it
void st_crt0_body(void) { a_1000_5006(); }
